/**
 * Duas with meaning (29 Nov 2026; MY-PLANS IDEA-BANK "Duas collection (Sehri, Iftar, travel, sleeping, eating) hi/en/bn").
 * Pages: /dua/ hub + /dua/<slug>/ in hi (Arabic + Devanagari pronunciation + Hindi meaning), en (Arabic + English letters +
 * English meaning) and bn (Arabic + Bengali pronunciation + Bengali meaning). Pairs with /namaz-time/ and /ramzan/.
 * Quran text: never typed by hand — sliced from src/quran-text.mjs (Tanzil, verbatim, credited); the build stops if a slice
 * is not found. Hadith duas: the common reading from the named collections. Pronunciation, meanings, background and FAQ
 * are our own writing.
 * line = [arabic, roman, hindi pronunciation, bengali pronunciation, hindi meaning, english meaning, bengali meaning]
 */
import { QURAN } from './quran-text.mjs';

// q(ref, a, b): words a..b-1 of a verse (negative = from the end) — slices Tanzil text, never retyped Arabic
const q = (ref, a = 0, b) => {
  const w = (QURAN[ref] || '').split(' ').filter(Boolean);
  if (!w.length) throw new Error(`dua.mjs: Quran ${ref} missing in quran-text.mjs`);
  const out = w.slice(a, b).join(' ');
  if (!out) throw new Error(`dua.mjs: empty slice of Quran ${ref}`);
  return out;
};
const KURSI = QURAN['2:255'].split(/(?<=[ۚۗۖ])\s+/);
if (KURSI.length !== 9) throw new Error(`dua.mjs: Ayatul Kursi split into ${KURSI.length} parts, expected 9`);

